package com.company.tpm.employee; import com.company.tpm.common.BaseEntity; import com.company.tpm.organization.*; import jakarta.persistence.*;
@Entity @Table(name="employees") public class Employee extends BaseEntity{@Column(nullable=false,unique=true,length=30)private String staffId;@Column(nullable=false)private String fullName;@ManyToOne(fetch=FetchType.LAZY)private Department department;@ManyToOne(fetch=FetchType.LAZY)private Section section;@ManyToOne(fetch=FetchType.LAZY)private Position position;private String shift;private String location;@ManyToOne(fetch=FetchType.LAZY)private Employee supervisor;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status=Status.ACTIVE;public enum Status{ACTIVE,INACTIVE,TERMINATED}protected Employee(){}public Employee(String id,String name){staffId=id;fullName=name;}public String getStaffId(){return staffId;}public String getFullName(){return fullName;}public Department getDepartment(){return department;}public Section getSection(){return section;}public Position getPosition(){return position;}public String getShift(){return shift;}public String getLocation(){return location;}public Employee getSupervisor(){return supervisor;}public Status getStatus(){return status;}public void update(String name,String shift,String location){fullName=name;this.shift=shift;this.location=location;}public void deactivate(){status=Status.INACTIVE;}}
